3	package memos.store;
4	
5	option go_package = "gen/store";
6	
7	message IdentityProvider {
8	  int32 id = 1;
9	  string name = 2;
10	
11	  enum Type {
12	    TYPE_UNSPECIFIED = 0;
13	    OAUTH2 = 1;
14	  }
15	  Type type = 3;
16	  string identifier_filter = 4;
17	  IdentityProviderConfig config = 5;
18	  string uid = 6;
19	}
20	
21	message IdentityProviderConfig {
22	  oneof config {
23	    OAuth2Config oauth2_config = 1;
24	  }
25	}
26	
27	message FieldMapping {
28	  string identifier = 1;
29	  string display_name = 2;
30	  string email = 3;
31	  string avatar_url = 4;
32	}
33	
34	message OAuth2Config {
35	  string client_id = 1;
36	  string client_secret = 2;
37	  string auth_url = 3;
38	  string token_url = 4;
39	  string user_info_url = 5;
40	  repeated string scopes = 6;
41	  FieldMapping field_mapping = 7;
42	}
